    function stickerStarsLineStyle(opts, sizePx, extraStyle) {
        extraStyle = extraStyle || '';
        const px = parseFloat(String(sizePx)) || 12;
        extraStyle = extraStyle.replace(/font-weight:\s*\d+\s*;?/gi, '');
        return 'font-size:' + px + 'px!important;line-height:1!important;font-weight:800!important;' + extraStyle;
    }

    function stickerRibbonStarLineStyle(opts, ribbonDark) {
        const px = resolveStarSize(opts, 11);
        const resolved = resolveStarColorFromOpts(opts);
        const color = resolved.multicolour ? DEFAULT_STAR_COLOR : (resolved.hex || (ribbonDark ? '#FBBF24' : DEFAULT_STAR_COLOR));
        return 'font-size:' + px + 'px!important;line-height:1!important;font-weight:800!important;color:' + color + ';letter-spacing:.02em;';
    }

    function isGenericLightTypoSeed(raw) {
        const hex = String(raw || '').trim().toLowerCase();
        return hex === '#334155' || hex === '#0f172a' || hex === '#1e293b' || hex === '#475569' || hex === '#64748b'
            || hex === '#24354c' || hex === '#253448' || hex === '#26374e' || hex === '#263649' || hex === '#1a3154' || hex === '#425775';
    }

    function stickerShellTypoColor(opts, role, fallback) {
        const key = 'typo_' + role + '_color';
        const raw = opts && String(opts[key] || '').trim();
        const shell = String(fallback || '#ffffff').trim().toLowerCase();
        const shellIsInkOnColor = shell === '#ffffff' || shell === '#fff' || shell === '#f8fafc';
        if (!raw || (shellIsInkOnColor && isGenericLightTypoSeed(raw))) return fallback || '#ffffff';
        if (isMulticolourColor(raw)) return fallback || '#ffffff';
        if (/^#([0-9A-Fa-f]{3}|[0-9A-Fa-f]{6})$/i.test(raw)) return raw;
        if (/^rgba?\(/i.test(raw)) return raw;
        return fallback || '#ffffff';
    }

    function stickerOnShellLabelStyle(opts, fallbackColor, extraStyle) {
        extraStyle = extraStyle || '';
        const color = stickerShellTypoColor(opts, 'rating_label', fallbackColor || '#ffffff');
        return typoSizeDecl(opts, 'rating_label', '14px') + typoWeightDecl(opts, 'rating_label', 600) + typoColorInlineDecl(color) + extraStyle;
    }

    function stickerOnShellValueStyle(opts, fallbackColor, extraStyle) {
        extraStyle = extraStyle || '';
        const color = stickerShellTypoColor(opts, 'rating_value', fallbackColor || '#ffffff');
        return typoSizeDecl(opts, 'rating_value', '44px') + 'line-height:1!important;' + typoWeightDecl(opts, 'rating_value', 600) + typoColorInlineDecl(color) + extraStyle;
    }

    function stickerOnShellReviewCountStyle(opts, fallbackColor, extraStyle) {
        extraStyle = extraStyle || '';
        const color = stickerShellTypoColor(opts, 'review_count', fallbackColor || '#64748b');
        return typoSizeDecl(opts, 'review_count', '12px') + typoWeightDecl(opts, 'review_count', 400) + 'color:' + color + ';line-height:1.2!important;' + extraStyle;
    }

    function normalizeFontPreset(slug) {
        slug = String(slug || 'inter').toLowerCase();
        return FONT_PRESETS[slug] ? slug : 'inter';
    }

    function fontFamilyFromOpts(opts) {
        opts = opts || {};
        if (opts.font_source === 'inherit') return 'inherit';
        const slug = normalizeFontPreset(opts.font_family_preset);
        return FONT_PRESETS[slug] || FONT_PRESETS.inter;
    }

    function cssFontFamilyVarValue(stack) {
        stack = String(stack || 'inherit').trim();
        if (!stack || stack === 'inherit') return 'inherit';
        return stack.replace(/"/g, "'");
    }

    function cssFontFamilyInlineValue(stack) {
        return cssFontFamilyVarValue(stack);
    }

    function typoFontFamilyDecl(opts) {
        const stack = fontFamilyFromOpts(opts);
        if (!stack || stack === 'inherit') return '';
        return 'font-family:' + cssFontFamilyInlineValue(stack) + '!important;';
    }

    function typoColorDecl(opts, role, theme, fallback) {
        const sem = typoSemantics(theme || (opts && opts.theme) || 'light', opts);
        const color = resolveTypoColor(opts, role, sem) || fallback || sem.fg;
        return typoColorInlineDecl(color);
    }

    let typoScopeCounter = 0;

    
    function typoScopeIdTaken(id) {
        if (typeof document === 'undefined') return false;
        return !!(document.querySelector('[data-grw-typo-scope="' + id + '"]')
            || document.querySelector('style[data-grw-config-typo-' + id + ']'));
    }

    function typoScopeIdForRoot(root) {
        if (!root) return 'grw0';
        const existing = root.getAttribute('data-grw-typo-scope');
        if (existing) return existing;
        const mount = root.closest ? root.closest('.grwidget-embed,[data-grwidget-key],[data-grwidget]') : null;
        const key = (mount && (mount.getAttribute('data-grwidget-key') || mount.getAttribute('data-grwidget'))) || '';
        let id = key ? ('k-' + String(key).replace(/[^a-zA-Z0-9_-]/g, '')) : '';
        while (!id || (!key && typoScopeIdTaken(id))) {
            id = 'g' + (++typoScopeCounter);
        }
        L.attribute(root, 'data-grw-typo-scope', id, null);
        return id;
    }

    function configDrawerHeaderCountRule(scope, opts) {
        const role = flyoutTypoRole(opts, 'flyout_review_count', 'review_count');
        const color = drawerHeaderReviewCountColor(opts);
        const size = resolvedTypoSize(opts, role, '12px');
        const weight = resolvedTypoWeight(opts, role, 400);
        return scope + ' .grw-drawer-header__count{' + typoColorInlineDecl(color) + 'font-size:' + size + '!important;font-weight:' + weight + '!important;' + typoFontFamilyDecl(opts) + '}';
    }

    function configTypoColorDecl(opts, role, theme) {
        const sem = typoSemantics(theme, opts);
        let custom = sanitizeTypoColor(opts && opts['typo_' + role + '_color']);
        const themeName = String(theme || (opts && opts.theme) || '').toLowerCase();
        
        
        if (custom && themeName === 'dark' && isGenericLightTypoSeed(custom)) custom = '';
        if (custom === 'multicolour') return typoColorInlineDecl(GOOGLE_BLUE);
        if (custom) return typoColorInlineDecl(custom);
        if (role === 'flyout_button') {
            const panelText = sanitizeTypoColor(opts && opts.flyout_button_text);
            if (panelText && panelText !== 'multicolour') return typoColorInlineDecl(panelText);
        }
        
        
        const semantic = typoColorSemantic(role);
        if (semantic === 'fg') {
            return 'color:var(--grw-text-primary,' + sem.fg + ')!important;-webkit-text-fill-color:var(--grw-text-primary,' + sem.fg + ')!important;';
        }
        if (semantic === 'muted') {
            return 'color:var(--grw-text-muted,' + sem.muted + ')!important;-webkit-text-fill-color:var(--grw-text-muted,' + sem.muted + ')!important;';
        }
        return typoColorInlineDecl(sem[semantic] || sem.fg);
    }

    function configTypoRule(scope, selectors, opts, role, theme, fbSize, fbWeight) {
        const size = resolvedTypoSize(opts, role, fbSize || TYPO_DEFAULT_SIZES[role] || '14px');
        const weight = resolvedTypoWeight(opts, role, fbWeight == null ? 400 : fbWeight);
        const sel = selectors.split(',').map(function (s) { return scope + ' ' + s.trim(); }).join(',');
        return sel + '{' + configTypoColorDecl(opts, role, theme) + 'font-size:' + size + '!important;font-weight:' + weight + '!important;' + typoFontFamilyDecl(opts) + '}';
    }

    function configShellTypoRule(scope, selectors, opts, role, fbSize, fbWeight, shellFallback) {
        const color = stickerShellTypoColor(opts, role, shellFallback || '#ffffff');
        const size = resolvedTypoSize(opts, role, fbSize || TYPO_DEFAULT_SIZES[role] || '14px');
        const weight = resolvedTypoWeight(opts, role, fbWeight == null ? 400 : fbWeight);
        const sel = selectors.split(',').map(function (s) { return scope + ' ' + s.trim(); }).join(',');
        return sel + '{' + typoColorInlineDecl(color) + 'font-size:' + size + '!important;font-weight:' + weight + '!important;' + typoFontFamilyDecl(opts) + '}';
    }

