    function feedHeaderMobileCtaSpacingCss() {
        var sel =
            '.grw-embed[data-grw-layout^="feed_"] .grw-feed-header .grw-feed-header__cta,' +
            '[data-grw-marketing-preview][data-layout^="feed_"] .grw-feed-header .grw-feed-header__cta,' +
            '[data-wb-builder-preview][data-layout^="feed_"] .grw-feed-header .grw-feed-header__cta,' +
            '#grwi-customize-preview-mount[data-layout^="feed_"] .grw-feed-header .grw-feed-header__cta,' +
            '.grw-mock.grw-preview-showcase>.grw-feed-header .grw-feed-header__cta,' +
            '.grw-mock.grw-preview-carousel>.grw-feed-header .grw-feed-header__cta';
        return '@media(max-width:480px){' + sel + '{margin-top:0.5rem!important;}}';
    }

    const SPACING_SCALE_MULT = { compact: 0.7, default: 1, relaxed: 1.35 };
    const SPACING_BASE_PX = {
        padding_y: 14, padding_x: 22, gap_element: 14, gap_inner: 6,
        gap_inline: 10, gap_section: 20, review_card_pad: 18,
    };

    function resolvedSpacing(opts) {
        opts = opts || {};
        let scale = opts.spacing_scale || 'default';
        if (!SPACING_SCALE_MULT[scale]) scale = 'default';
        const mult = SPACING_SCALE_MULT[scale];
        const resolve = function (baseKey, overrideKey, min, max) {
            const override = String(opts[overrideKey] || '').trim();
            if (override) {
                return parseInt(sanitizeCssSize(override, SPACING_BASE_PX[baseKey] + 'px', 0, 48), 10);
            }
            return Math.max(min, Math.min(max, Math.round(SPACING_BASE_PX[baseKey] * mult)));
        };
        const paddingY = resolve('padding_y', 'spacing_padding_y', 4, 48);
        const paddingX = resolve('padding_x', 'spacing_padding_x', 4, 48);
        const resolveWidgetSide = function (sideKey, fallback) {
            const raw = String(opts[sideKey] || '').trim();
            if (raw) {
                return parseInt(sanitizeCssSize(raw, fallback + 'px', 0, 48), 10);
            }
            return fallback;
        };
        const layoutKey = String((opts && opts.layout) || '');
        const badgeStyle = String((opts && opts.badge_style) || '');
        const reviewsButtonPad = layoutKey === 'badge_reviews_button' || badgeStyle === 'reviews_button';
        const sideFallbackY = reviewsButtonPad ? 19 : paddingY;
        const sideFallbackX = reviewsButtonPad ? 22 : paddingX;
        const paddingTop = resolveWidgetSide('widget_padding_top', sideFallbackY);
        const paddingRight = resolveWidgetSide('widget_padding_right', sideFallbackX);
        const paddingBottom = resolveWidgetSide('widget_padding_bottom', sideFallbackY);
        const paddingLeft = resolveWidgetSide('widget_padding_left', sideFallbackX);
        const feedHeaderPaddingTop = resolveWidgetSide('feed_header_padding_top', resolveWidgetSide('widget_padding_top', paddingY));
        const feedHeaderPaddingRight = resolveWidgetSide('feed_header_padding_right', resolveWidgetSide('widget_padding_right', paddingX));
        const feedHeaderPaddingBottom = resolveWidgetSide('feed_header_padding_bottom', resolveWidgetSide('widget_padding_bottom', paddingY));
        const feedHeaderPaddingLeft = resolveWidgetSide('feed_header_padding_left', resolveWidgetSide('widget_padding_left', paddingX));
        const gapElement = resolve('gap_element', 'spacing_gap', 2, 32);
        const gapSection = resolve('gap_section', 'spacing_section_gap', 4, 48);
        const gapInner = Math.max(2, Math.min(16, Math.round(SPACING_BASE_PX.gap_inner * mult)));
        const gapInline = Math.max(4, Math.min(24, Math.round(SPACING_BASE_PX.gap_inline * mult)));
        const reviewCardPad = Math.max(8, Math.min(32, Math.round(SPACING_BASE_PX.review_card_pad * mult)));
        const elementKeys = [
            'logo', 'rating_label', 'rating_value', 'stars', 'review_count', 'verified_badge', 'business_name', 'cta',
            'showcase_title', 'reviews_button_title', 'header_stars', 'slide_stars', 'card_stars', 'review_card_text', 'review_card_author', 'review_card_date',
            'ai_summary_icon', 'ai_summary_pill', 'ai_summary_label', 'ai_summary_stars', 'ai_summary_headline', 'ai_summary_body', 'ai_summary_themes',
        ];
        const normalizeElementMargin = function (value) {
            const num = parseInt(value, 10);
            if (isNaN(num) || num < 0) return 0;
            return Math.max(0, Math.min(64, num));
        };
        const elementMarginValue = function (opts, element, side) {
            const key = element + '_margin_' + side;
            const raw = opts && opts[key];
            if (raw === undefined || raw === null || raw === '') {
                return (element === 'verified_badge' && side === 'left') ? 5 : 0;
            }
            return normalizeElementMargin(raw);
        };
        let css = '--grw-padding-y:' + paddingY + 'px;--grw-padding-x:' + paddingX + 'px;' +
            '--grw-padding-top:' + paddingTop + 'px;--grw-padding-right:' + paddingRight + 'px;' +
            '--grw-padding-bottom:' + paddingBottom + 'px;--grw-padding-left:' + paddingLeft + 'px;' +
            '--grw-feed-header-padding-top:' + feedHeaderPaddingTop + 'px;--grw-feed-header-padding-right:' + feedHeaderPaddingRight + 'px;' +
            '--grw-feed-header-padding-bottom:' + feedHeaderPaddingBottom + 'px;--grw-feed-header-padding-left:' + feedHeaderPaddingLeft + 'px;' +
            '--grw-gap-element:' + gapElement + 'px;--grw-gap-inner:' + gapInner + 'px;' +
            '--grw-gap-inline:' + gapInline + 'px;--grw-gap-section:' + gapSection + 'px;' +
            '--grw-review-card-pad:' + reviewCardPad + 'px;' +
            '--grw-padding-y-mobile:' + Math.max(4, Math.round(paddingY * 0.72)) + 'px;' +
            '--grw-padding-x-mobile:' + Math.max(4, Math.round(paddingX * 0.64)) + 'px;' +
            '--grw-padding-top-mobile:' + Math.max(4, Math.round(paddingTop * 0.72)) + 'px;' +
            '--grw-padding-right-mobile:' + Math.max(4, Math.round(paddingRight * 0.64)) + 'px;' +
            '--grw-padding-bottom-mobile:' + Math.max(4, Math.round(paddingBottom * 0.72)) + 'px;' +
            '--grw-padding-left-mobile:' + Math.max(4, Math.round(paddingLeft * 0.64)) + 'px;' +
            '--grw-feed-header-padding-top-mobile:' + Math.max(4, Math.round(feedHeaderPaddingTop * 0.72)) + 'px;' +
            '--grw-feed-header-padding-right-mobile:' + Math.max(4, Math.round(feedHeaderPaddingRight * 0.64)) + 'px;' +
            '--grw-feed-header-padding-bottom-mobile:' + Math.max(4, Math.round(feedHeaderPaddingBottom * 0.72)) + 'px;' +
            '--grw-feed-header-padding-left-mobile:' + Math.max(4, Math.round(feedHeaderPaddingLeft * 0.64)) + 'px;' +
            '--grw-gap-section-mobile:' + Math.max(4, Math.round(gapSection * 0.6)) + 'px;';
        elementKeys.forEach(function (element) {
            ['top', 'bottom', 'left', 'right'].forEach(function (side) {
                css += '--grw-' + element + '-margin-' + side + ':' + elementMarginValue(opts, element, side) + 'px;';
            });
        });
        return {
            css: css,
            padding_y: paddingY,
            padding_x: paddingX,
            padding_top: paddingTop,
            padding_right: paddingRight,
            padding_bottom: paddingBottom,
            padding_left: paddingLeft,
            gap_element: gapElement,
        };
    }

    function spacingShellPaddingValue() {
        return 'var(--grw-padding-top,var(--grw-padding-y,14px)) var(--grw-padding-right,var(--grw-padding-x,22px)) var(--grw-padding-bottom,var(--grw-padding-y,14px)) var(--grw-padding-left,var(--grw-padding-x,22px))';
    }

    function spacingFeedHeaderPaddingValue() {
        return 'var(--grw-feed-header-padding-top,var(--grw-padding-y,14px)) var(--grw-feed-header-padding-right,var(--grw-padding-x,22px)) var(--grw-feed-header-padding-bottom,var(--grw-padding-y,14px)) var(--grw-feed-header-padding-left,var(--grw-padding-x,22px))';
    }

    
