    function injectTypographyStyles() {
        if (typographyStylesInjected) return;
        let style = document.querySelector('style[data-grw-typography]');
        if (style) {
            typographyStylesInjected = true;
            return;
        }
        typographyStylesInjected = true;
        style = document.createElement('style');
        L.attribute(style, 'data-grw-typography', '1', null);
        L.text(style, typographyStylesCss(), null);
        (document.head || document.documentElement).appendChild(style);
    }

