    function embedOnlySpacingCss(selectorRules) {
        return '@scope(body:not(.wb-page))to(#builder){' + String(selectorRules || '') + '}';
    }

    function isBuilderPreviewContext(opts) {
        if (opts && (opts.builderPreview || opts.layoutPickerPreview)) return true;
        return typeof isBuilderPreviewPage === 'function' && isBuilderPreviewPage();
    }

    function isLayoutPickerPreviewContext(opts) {
        return !!(opts && opts.layoutPickerPreview);
    }

    function disableFlyoutForLayoutPickerPreview(opts) {
        if (!isLayoutPickerPreviewContext(opts)) return opts;
        opts.flyout_enabled = false;
        opts.review_click_action = 'none';
        return opts;
    }

    
    function layoutPickerPreviewCssRoot(extraSelector) {
        extraSelector = extraSelector || '';
        return '.wb-layout-card__mock' + extraSelector + ',.grw-layout-card__mock' + extraSelector + ',[data-grw-layout-picker-preview]' + extraSelector;
    }

    
    function layoutPickerPreviewClickShieldCss() {
        const selectors = [
            '[data-grw-drawer-trigger]',
            '.grw-view-all-reviews',
            '.grw-show-more-reviews',
            '.grw-badge[role="button"]',
            '.grw-pill-chip[data-grw-drawer-trigger]',
        ];
        return selectors.map(function (selector) {
            return layoutPickerPreviewDescendant('', selector);
        }).join(',') + '{pointer-events:none!important;cursor:default!important;}';
    }

    
    function layoutPickerPreviewDescendant(scopeSelector, descendantSelector) {
        scopeSelector = scopeSelector || '';
        descendantSelector = descendantSelector || '';
        return '.wb-layout-card__mock' + scopeSelector + ' ' + descendantSelector +
            ',.grw-layout-card__mock' + scopeSelector + ' ' + descendantSelector +
            ',[data-grw-layout-picker-preview]' + scopeSelector + ' ' + descendantSelector;
    }

    
    function layoutCardPreviewDescendant(scopeSelector, descendantSelector) {
        scopeSelector = scopeSelector || '';
        descendantSelector = descendantSelector || '';
        return '.wb-layout-card__mock' + scopeSelector + ' ' + descendantSelector +
            ',.grw-layout-card__mock' + scopeSelector + ' ' + descendantSelector +
            ',.grw-layout-card__preview--theme-light .grw-layout-card__mock' + scopeSelector + ' ' + descendantSelector +
            ',.wb-layout-card__preview--theme-light .wb-layout-card__mock' + scopeSelector + ' ' + descendantSelector;
    }

    function layoutPickerPreviewFilledClass(canonicalLayout) {
        const key = String(canonicalLayout || '');
        if (key.indexOf('feed_') === 0) return 'w-full min-w-0 text-left';
        if (key.indexOf('sticker_') === 0) return 'w-full min-w-0 flex items-center justify-center';
        if (key === 'badge_review_request') return 'block w-full min-w-0';
        if (isBadgeCanonicalLayout(key)) return 'w-max max-w-full inline-block';
        return 'w-max max-w-full inline-block';
    }

