    function stickerRibbonShapeInlineStyle(opts, ribbonStretch) {
        if (isBuilderPreviewContext(opts)) {
            return ribbonStretch
                ? 'display:flex;align-items:stretch;overflow:visible;flex-shrink:1;min-width:min-content;width:100%;max-width:100%;'
                : 'display:inline-flex;align-items:stretch;overflow:visible;flex-shrink:0;min-width:min-content;width:max-content;max-width:100%;';
        }
        return ribbonStretch
            ? 'display:flex;align-items:stretch;overflow:hidden;flex-shrink:1;min-width:0;width:100%;max-width:100%;'
            : 'display:inline-flex;align-items:stretch;overflow:hidden;flex-shrink:0;min-width:200px;max-width:100%;';
    }

    function stickerRibbonBodyJustify(opts) {
        const align = normalizedAlignmentOpt(opts, 'pill');
        if (align === 'center') return 'center';
        if (align === 'right') return 'flex-end';
        return 'flex-start';
    }

    function stickerRibbonContentColumnStyle() {
        return 'display:flex;flex-direction:column;gap:2px;min-width:min-content;flex:0 1 auto;align-items:flex-start;text-align:left;';
    }

    function stickerRibbonRatingRowAlignStyle(opts) {
        return 'justify-content:flex-start;';
    }

    function stickerRibbonContentAlignStyle(opts) {
        return {
            column: stickerRibbonContentColumnStyle(),
            row: stickerRibbonRatingRowAlignStyle(opts),
        };
    }

    function stickerRibbonBodyInlineStyle(opts) {
        const justify = stickerRibbonBodyJustify(opts);
        const padding = 'padding:' + stickerRibbonBodyPaddingValue() + ';';
        if (isBuilderPreviewContext(opts)) {
            return 'display:flex;align-items:center;gap:8px;min-width:min-content;flex:0 1 auto;justify-content:' + justify + ';' + padding;
        }
        return 'display:flex;align-items:center;gap:8px;min-width:0;flex:1;justify-content:' + justify + ';' + padding;
    }

    function resetBuilderCanvasScroll() {
        document.querySelectorAll('.wb-canvas-wrap,.wb-canvas-stage').forEach(function (el) {
            if (!el) return;
            if (el.scrollLeft !== 0) el.scrollLeft = 0;
        });
    }

    function ensureBuilderPreviewFullyVisible() {
        if (typeof isBuilderPreviewPage === 'function' && !isBuilderPreviewPage() && !window.__wbMarketingGuestBuilder) return;
        const stage = document.querySelector('#builder .wb-canvas-stage,.wb-canvas-stage');
        const wrap = document.querySelector('#builder .wb-canvas-wrap,.wb-canvas-wrap');
        [wrap, stage].forEach(function (el) {
            if (!el) return;
            el.scrollLeft = 0;
            
        });
        const mount = (typeof window.getBuilderPreviewEl === 'function' ? window.getBuilderPreviewEl() : null)
            || document.querySelector('.wb-preview-root>[data-wb-builder-preview]');
        if (mount) mount.style.marginLeft = '';
    }

    
    const AI_SUMMARY_STAR_GRADIENT = 'linear-gradient(135deg,#93C5FD 0%,#60A5FA 32%,#3B82F6 64%,#1D4ED8 100%)';
    const AI_SUMMARY_STAR_GRADIENT_DARK = 'linear-gradient(135deg,#DBEAFE 0%,#BFDBFE 30%,#93C5FD 62%,#60A5FA 100%)';
