    const AI_SUMMARY_STAR_GRADIENT_DARK_DECL = '--grw-ai-star-gradient:' + AI_SUMMARY_STAR_GRADIENT_DARK + ';';

    function aiSummaryStarColorOverride(opts) {
        const raw = String((opts && opts.ai_summary_star_color) || '').trim();
        if (!raw) return '';
        
        return /^(?:#[0-9a-fA-F]{3,8}|rgba?\([\d\s.,%]+\))$/.test(raw) ? raw : '';
    }

