    function injectExamplesPageLayoutCss() {
        if (typeof document === 'undefined' || !document.getElementById('examples-page')) return;
        let style = document.querySelector('style[data-grw-examples-layout]');
        if (!style) {
            style = document.createElement('style');
            L.attribute(style, 'data-grw-examples-layout', '1', null);
            (document.head || document.documentElement).appendChild(style);
        }
        L.text(style, examplesPageLayoutCss(), null);
    }

