    function sliderFeedNarrowReadingCss() {
        const roots = [
            '.grw-embed[data-grw-layout="feed_carousel"]',
            '.wb-preview-root [data-wb-builder-preview][data-layout="feed_carousel"]',
            '#grwi-customize-preview-mount[data-layout="feed_carousel"]',
            '.grw-typo-root[data-grw-layout="feed_carousel"]',
        ];
        const zero = [
            '.grw-google-tracer-inner',
            '.grw-preview-carousel-slide',
            '.grw-carousel-slide',
            '.grw-preview-carousel-slide__quote',
            '.grw-carousel-slide__quote',
            '.grw-preview-carousel-slide__quote>p',
            '.grw-carousel-slide__quote>p',
        ];
        const body = [
            '.grw-preview-carousel-body',
            '.grw-preview-carousel-viewport',
            '.grw-carousel-viewport',
            '.grw-carousel-body',
        ];
        function join(parts) {
            const out = [];
            roots.forEach(function (root) {
                parts.forEach(function (part) { out.push(root + ' ' + part); });
            });
            return out.join(',');
        }
        const clear = '{padding-left:0!important;padding-right:0!important;}';
        return '@container grw-widget (max-width:480px){' + join(zero) + clear + join(body) + '{padding-left:max(12px,var(--grw-arrow-size,32px))!important;padding-right:max(12px,var(--grw-arrow-size,32px))!important;}}' +
            '@container grw-widget (max-width:360px){' + join(body) + '{padding-left:max(10px,var(--grw-arrow-size,28px))!important;padding-right:max(10px,var(--grw-arrow-size,28px))!important;}}';
    }

