    function initPreviewMiniSlider(host) {
        const root = host.querySelector('[data-grw-mini-slider]');
        if (!root || root.__grwMiniBound) return;
        root.__grwMiniBound = true;
        const dots = root.querySelectorAll('.grw-mini-slider-dots button');
        if (!dots.length) return;
        let index = 0;
        const card = root.querySelector('.grw-mini-slider-card');
        function paint() {
            const dot = dots[index] || dots[0];
            if (!dot || !card) return;
            const textEl = card.querySelector('.grw-mini-slider-text');
            const nameEl = card.querySelector('.grw-mini-slider-name');
            if (textEl) L.html(textEl, linkedReviewTextHtml(dot.getAttribute('data-mini-text') || ''), null);
            if (nameEl) L.text(nameEl, dot.getAttribute('data-mini-name') || '', null);
            const img = card.querySelector('.grw-mini-slider-avatar');
            const photo = dot.getAttribute('data-mini-photo') || '';
            if (img && photo && img.tagName === 'IMG') img.src = photo;
            dots.forEach(function (el, i) { L.attribute(el, 'aria-pressed', i === index ? 'true' : 'false', null); });
        }
        root.querySelectorAll('.grw-mini-slider-arrow').forEach(function (btn) {
            btn.addEventListener('click', function () {
                const step = parseInt(btn.getAttribute('data-step'), 10) || 1;
                index = (index + step + dots.length) % dots.length;
                paint();
            });
        });
        dots.forEach(function (dot) {
            dot.addEventListener('click', function () {
                index = parseInt(dot.getAttribute('data-mini'), 10) || 0;
                paint();
            });
        });
    }

    function initPreviewReputationSnapshot(host) {
        const root = host.querySelector('[data-grw-reputation-snapshot]');
        if (!root || root.__grwRsBound) return;
        root.__grwRsBound = true;
        const quoteEl = root.querySelector('[data-rs-quote]');
        const nameEl = root.querySelector('.grw-rs-quoted-name');
        function paintQuote(btn) {
            if (!btn) return;
            if (quoteEl) {
                L.html(quoteEl, linkedReviewTextHtml(btn.getAttribute('data-rs-quote') || ''), null);
                quoteEl.classList.remove('grw-rs-quote-enter');
                void quoteEl.offsetWidth;
                quoteEl.classList.add('grw-rs-quote-enter');
            }
            if (nameEl) L.text(nameEl, btn.getAttribute('data-rs-name') || '', null);
        }
        root.querySelectorAll('.grw-rs-face').forEach(function (btn) {
            btn.addEventListener('click', function () {
                root.querySelectorAll('.grw-rs-face').forEach(function (el) { L.attribute(el, 'aria-pressed', el === btn ? 'true' : 'false', null); });
                paintQuote(btn);
            });
        });
    }

