    const GRID_PLACEHOLDERS = [
        { name: 'Alex R.', rating: 5, text: 'Fast, friendly, fair pricing — could not recommend more.', gradient: GRADIENTS[0], initials: 'AR' },
        { name: 'Jordan P.', rating: 5, text: 'Our go-to every single time. Always excellent.', gradient: GRADIENTS[1], initials: 'JP' },
        { name: 'Sam T.', rating: 4, text: 'Great results, would book again without hesitation.', gradient: GRADIENTS[2], initials: 'ST' },
        { name: 'Casey L.', rating: 5, text: 'Five stars. Professional from start to finish.', gradient: GRADIENTS[3], initials: 'CL' },
    ];

    function builderPreviewEmptyMessage(opts, layout) {
        if (!opts || !opts.builderPreview) {
            return (L.msg("builder.no_public"));
        }
        const filter = reviewImageFilterForContext(opts, 'widget', layout || opts.layout || '');
        if (filter === 'with_images') {
            return 'No reviews with uploaded images match this filter. Try “All reviews” or sync more Google reviews.';
        }
        if (filter === 'without_images') {
            return 'No reviews without images match this filter. Try “All reviews” or adjust your selection.';
        }
        if (previewHasActiveContentFilters(opts)) {
            return (L.msg("builder.no_match"));
        }
        const rawReviews = (opts && opts.reviews) || [];
        if (rawReviews.length && hiddenPreviewReviewIds(opts).length && applyHiddenReviewsForPreview(rawReviews, opts).length === 0) {
            return (L.msg("builder.all_hidden"));
        }
        // The builder passes already-visible reviews, so an empty list here can
        // mean every review was hidden. The curator still has the full set.
        const curator = (typeof window !== 'undefined') ? window.WbReviewsCurator : null;
        if (curator && typeof curator.getBaseReviews === 'function' && typeof curator.getState === 'function') {
            const base = curator.getBaseReviews() || [];
            const hidden = ((curator.getState() || {}).hidden_review_ids) || [];
            if (base.length && hidden.length) {
                const shown = base.filter(function (review) {
                    const id = review && (review.id || review.review_id);
                    return id && hidden.indexOf(id) === -1;
                });
                if (!shown.length) {
                    return (L.msg("builder.all_hidden"));
                }
            }
        }
        return (L.msg("builder.no_public"));
    }

    function previewReviewFixtureSupplied(opts) {
        opts = opts || {};
        if (Array.isArray(opts.reviews)) return true;
        if (opts.builderPreview && previewHasActiveContentFilters(opts)) return true;
        if (opts.builderPreview && hiddenPreviewReviewIds(opts).length) return true;
        return false;
    }

    function previewShouldKeepEmptyReviewSet(items, opts) {
        return !(items && items.length) && previewReviewFixtureSupplied(opts);
    }

    function previewReviewPlaceholderSource(items, opts) {
        if (items && items.length) return items;
        // A supplied list that filters down to nothing is empty on purpose.
        // Placeholders are only for a mount that has not been given a fixture.
        if (previewShouldKeepEmptyReviewSet(items, opts)) return [];
        if (opts && opts.builderPreview) {
            const layout = (opts && opts.layout) || '';
            const filter = reviewImageFilterForContext(opts, 'widget', layout);
            if (filter !== 'all') return [];
        }
        return GRID_PLACEHOLDERS;
    }

    function gridMiniCard(review, highlighted, showReviewImages, t, opts) {
        opts = opts || {};
        const ring = highlighted ? ' ring-2 ring-brand/30' : '';
        const plain = reviewBreaksToNewlines(review.text);
        const text = plain.length > 90 ? plain.slice(0, 87) + '…' : plain;
        const avatar = review.name
            ? '<div class="flex items-center gap-2 mb-2">' + authorAvatarHtml(review, true, opts).replace('w-10 h-10', 'w-7 h-7').replace('width="40" height="40"', 'width="28" height="28"') +
              '<span class="text-[11px] font-bold truncate ' + t.reviewName + '">' + esc(review.name) + '</span></div>'
            : '';
        return '<div class="grw-grid-card grw-review-card rounded-2xl border ' + t.gridCard + ring + '">' +
            avatar +
            previewStarsMarkup(review.rating, cardStarOpts(opts), t, 12, 'text-xs mb-1.5') +
            '<p class="text-[11px] leading-snug ' + t.gridText + '">“' + linkedReviewTextHtml(text) + '”</p>' +
            reviewPhotosHtml(review, showReviewImages) +
            '</div>';
    }

    function gridCardsFromReviews(reviews, opts, t) {
        const showReviewImages = showReviewImagesOpt(opts);
        if (opts && opts.loading) {
            return emptyReviewsBlock('Loading Google reviews…', t);
        }
        if (opts && opts.reviewsError) {
            return emptyReviewsBlock(opts.reviewsError, t);
        }
        const items = reviewsForPreview({ reviews: reviews }, opts);
        const source = previewReviewPlaceholderSource(items, opts);
        if (!source.length) {
            return emptyReviewsBlock(builderPreviewEmptyMessage(opts, 'grid'), t);
        }
        const cards = source.slice(0, 4).map(function (r, i) {
            return gridMiniCard(r, i === 0, showReviewImages, t, opts);
        }).join('');
        return '<div class="grw-reviews-grid">' + cards + '</div>';
    }

    function gridLayout(name, rating, count, reviews, opts) {
        const gridOpts = Object.assign({}, opts || {}, {
            feed_style: 'grid',
            showcase_display_mode: 'grid',
            showcase_carousel: false,
        });
        if (gridOpts.showcase_rows == null && gridOpts.showcaseRows == null) {
            gridOpts.showcase_rows = 2;
        }
        return showcaseLayout(name, rating, count, reviews, gridOpts, gridOpts.previewPlace);
    }

    function isExamplesMasonry(opts) {
        return !!(opts && opts.previewVariant === 'examples-masonry');
    }

    function masonryExamplesLineClamp(reviewIndex, hasPhotos) {
        const clamps = hasPhotos ? [4, 2, 5, 2, 4, 2, 5, 3] : [11, 2, 9, 3, 12, 2, 8, 4];
        return clamps[reviewIndex % clamps.length];
    }

    function gridExamplesRowHasPhoto(reviewIndex, opts) {
        if (!isShowcaseStaticGrid(opts)) return false;
        if (!previewUsesDemoReviewPhotos(opts)) return false;
        const cols = showcaseGridColumns(opts);
        const row = Math.floor(reviewIndex / cols);
        const rowStart = row * cols;
        const items = opts && opts._gridPreviewItems;
        for (let c = 0; c < cols; c++) {
            const idx = rowStart + c;
            if (items && items[idx] && reviewHasImages(items[idx])) return true;
            if (demoPhotosMode(opts) === 'selective' && isSelectiveDemoPhotoIndex(idx)) return true;
        }
        return false;
    }

    function gridExamplesRowHasSelectivePhoto(reviewIndex, opts) {
        return gridExamplesRowHasPhoto(reviewIndex, opts);
    }

    function gridExamplesLineClamp(reviewIndex, hasPhotos, opts, reviewText) {
        if (isShowcaseStaticGrid(opts) || feedStyleOpt(opts) === 'grid') {
            return hasPhotos ? FEED_LINE_CLAMP_WITH_PHOTOS : FEED_LINE_CLAMP_GRID_NO_PHOTOS;
        }
        return null;
    }

    function gridExamplesPhotoPlaceholderHtml(reviewIndex, review, showReviewImages, opts) {
        // Row equalization + adaptive text clamp replace photo-slot placeholders: no-photo
        // cards in a photo row reuse that height for review text instead of empty chrome.
        if (!previewUsesDemoReviewPhotos(opts)) return '';
        return '';
    }

    function masonryCard(review, tall, showReviewImages, t, opts, reviewIndex) {
        let lineClamp = tall ? 5 : 4;
        let isTall = tall;
        if (isExamplesMasonry(opts)) {
            lineClamp = masonryExamplesLineClamp(reviewIndex, showReviewImages && reviewHasImages(review));
            isTall = lineClamp >= 8;
        }
        const masonryOpts = Object.assign({}, opts || {}, { _masonryTall: isTall });
        return feedReviewCardHtml(review, showReviewImages, t, masonryOpts, true, null, 'masonry', reviewIndex);
    }

    function masonryReviewCardEl(el) {
        if (!el || el.nodeType !== 1) return false;
        if (el.classList.contains('grw-ai-summary-card')) return false;
        return el.classList.contains('grw-masonry-item')
            || el.classList.contains('grw-feed-review-card')
            || el.hasAttribute('data-grw-review');
    }

    function masonryConfiguredColumns(container, width) {
        const style = window.getComputedStyle(container);
        let desktop = parseInt(style.getPropertyValue('--grw-feed-columns'), 10);
        let tablet = parseInt(style.getPropertyValue('--grw-feed-columns-md'), 10);
        if (!(desktop > 0)) desktop = 3;
        if (!(tablet > 0)) tablet = Math.min(2, desktop);
        if (width > 0 && width <= 479) return 1;
        if (width > 0 && width <= 880) return Math.min(tablet, desktop);
        return desktop;
    }

    function collectMasonryNodes(container) {
        const nodes = [];
        Array.prototype.forEach.call(container.children, function (child) {
            if (child.classList && child.classList.contains('grw-masonry-col')) {
                Array.prototype.forEach.call(child.children, function (nested) { nodes.push(nested); });
                return;
            }
            nodes.push(child);
        });
        return nodes;
    }

    function masonryCardHeight(el) {
        const mb = parseFloat(window.getComputedStyle(el).marginBottom) || 0;
        return (el.offsetHeight || 1) + mb;
    }

    /**
     * CSS multi-column balances by height, so one tall photo can leave a column empty.
     * Pack into real columns: never more columns than reviews, and every column gets
     * at least one review when there are enough reviews.
     */
    function packMasonryColumns(container) {
        if (!container || !container.classList || !container.classList.contains('grw-masonry-columns')) return;
        const width = container.clientWidth || 0;
        if (width < 2) {
            if (!container.__grwMasonryRetry) {
                container.__grwMasonryRetry = true;
                requestAnimationFrame(function () { packMasonryColumns(container); });
            }
            return;
        }
        container.__grwMasonryRetry = false;
        const nodes = collectMasonryNodes(container);
        const extras = [];
        const reviews = [];
        nodes.forEach(function (el) {
            if (masonryReviewCardEl(el)) reviews.push(el);
            else extras.push(el);
        });
        let nextOrder = 0;
        reviews.forEach(function (el) {
            const n = parseInt(el.getAttribute('data-grw-masonry-order'), 10);
            if (!isNaN(n) && n >= nextOrder) nextOrder = n + 1;
        });
        reviews.forEach(function (el) {
            if (!el.hasAttribute('data-grw-masonry-order')) {
                L.attribute(el, 'data-grw-masonry-order', String(nextOrder), null);
                nextOrder += 1;
            }
        });
        reviews.sort(function (a, b) {
            return parseInt(a.getAttribute('data-grw-masonry-order'), 10) - parseInt(b.getAttribute('data-grw-masonry-order'), 10);
        });
        let cols = masonryConfiguredColumns(container, width);
        if (reviews.length > 0) cols = Math.min(cols, reviews.length);
        else cols = 1;
        cols = Math.max(1, cols);
        const gap = parseFloat(window.getComputedStyle(container).columnGap) || 14;
        const colWidth = Math.max(1, (width - gap * (cols - 1)) / cols);
        const measurer = document.createElement('div');
        measurer.style.cssText = 'position:absolute;left:-9999px;top:0;visibility:hidden;pointer-events:none;width:' + colWidth + 'px;';
        document.body.appendChild(measurer);
        const heights = reviews.map(function (el) {
            measurer.appendChild(el);
            return masonryCardHeight(el);
        });
        const extraHeights = extras.map(function (el) {
            measurer.appendChild(el);
            return masonryCardHeight(el);
        });
        measurer.remove();
        const buckets = [];
        const colH = [];
        for (let c = 0; c < cols; c++) {
            buckets.push([]);
            colH.push(0);
        }
        const seed = Math.min(cols, reviews.length);
        for (let i = 0; i < seed; i++) {
            buckets[i].push(reviews[i]);
            colH[i] = heights[i] || 1;
        }
        for (let i = extras.length - 1; i >= 0; i--) {
            buckets[0].unshift(extras[i]);
            colH[0] += extraHeights[i] || 1;
        }
        for (let i = seed; i < reviews.length; i++) {
            let target = 0;
            for (let c = 1; c < cols; c++) {
                if (colH[c] < colH[target]) target = c;
            }
            buckets[target].push(reviews[i]);
            colH[target] += heights[i] || 1;
        }
        while (container.firstChild) container.removeChild(container.firstChild);
        buckets.forEach(function (bucket) {
            const col = document.createElement('div');
            col.className = 'grw-masonry-col';
            bucket.forEach(function (el) { col.appendChild(el); });
            container.appendChild(col);
        });
        container.classList.add('grw-masonry-columns--packed');
        L.attribute(container, 'data-grw-masonry-cols', String(cols), null);
    }

    function watchMasonryColumns(scope) {
        if (!scope || !scope.querySelectorAll) return;
        scope.querySelectorAll('.grw-masonry-columns').forEach(function (container) {
            packMasonryColumns(container);
            if (container.__grwMasonryWatch || typeof ResizeObserver === 'undefined') return;
            container.__grwMasonryWatch = true;
            let lastW = container.clientWidth;
            const ro = new ResizeObserver(function () {
                const w = container.clientWidth;
                const cols = masonryConfiguredColumns(container, w);
                const prev = parseInt(container.getAttribute('data-grw-masonry-cols'), 10) || 0;
                const reviewCount = container.querySelectorAll('.grw-masonry-item, .grw-feed-review-card').length;
                const target = reviewCount > 0 ? Math.min(cols, reviewCount) : prev;
                if (target === prev && Math.abs(w - lastW) < 16) return;
                lastW = w;
                packMasonryColumns(container);
            });
            ro.observe(container);
        });
    }

    function masonryLayout(name, rating, count, reviews, opts) {
        const t = tokensFromOpts(opts);
        const showReviewImages = showReviewImagesOpt(opts);
        let body;
        if (opts && opts.loading) {
            body = emptyReviewsBlock('Loading Google reviews…', t);
        } else if (opts && opts.reviewsError) {
            body = emptyReviewsBlock(opts.reviewsError, t);
        } else {
            const items = reviewsForPreview({ reviews: reviews }, opts);
            const source = previewReviewPlaceholderSource(items, opts);
            if (!source.length) {
                body = emptyReviewsBlock(builderPreviewEmptyMessage(opts, 'masonry'), t);
            } else {
                const tallPattern = [true, false, false, true, false, true, true, false];
                const initial = Math.min(feedInitialReviewCount(opts), source.length);
                const cards = source.slice(0, initial).map(function (r, i) {
                    return masonryCard(r, tallPattern[i % tallPattern.length], showReviewImages, t, opts, i);
                }).join('');
                const footer = feedReviewsFooterPreview(t, opts, opts.previewPlace, 'masonry', source.length, initial);
                const summaryCard = aiSummaryWrapHtml(opts, t, 'masonry', 'feed_masonry', source, opts && opts.previewPlace);
                body = '<div class="grw-masonry-columns grw-reviews-inline" data-grw-reviews-inline data-grw-visible-count="' + initial + '" style="' + feedGridCssVars(opts) + 'column-gap:var(--grw-gap-element,12px);width:100%;">' +
                    summaryCard + cards + '</div>' + footer;
            }
        }
        return wrapPreviewWidgetShell(
            feedWidgetTitlePreviewHtml(opts, t, 'masonry') +
            feedHeaderHtmlFromOpts(name, '', rating, count, opts, t, 'masonry', opts && opts.previewPlace) +
            body,
            opts,
            opts.theme,
            'grw-mock grw-widget-shell ' + previewShellShadowClass(opts) + ' w-full ' + t.shell,
            '',
            ' data-grw-preview-theme="' + esc((opts && opts.theme) || 'light') + '"'
        );
    }

    let achievementShieldUidSeq = 0;

    function nextAchievementShieldUid() {
        achievementShieldUidSeq += 1;
        return 'grw-achievement-shield-' + achievementShieldUidSeq;
    }

    function achievementGoldStarsRow(rating, starSize) {
        if (!hasDisplayRating(rating)) return '';
        starSize = starSize || 12;
        const filled = Math.min(5, Math.max(0, Math.round(Number(rating))));
        let row = '';
        for (let i = 0; i < 5; i++) {
            const fill = i < filled ? '#D4A012' : '#CBD5E1';
            row += '<svg width="' + starSize + '" height="' + starSize + '" viewBox="0 0 24 24" aria-hidden="true" style="display:block;flex-shrink:0;filter:drop-shadow(0 1px 0 rgba(255,255,255,.65));">' +
                '<path fill="' + fill + '" d="M12 2.4l2.47 5.01 5.53.8-4 3.9.94 5.5L12 15.9l-4.94 2.71.94-5.5-4-3.9 5.53-.8z"/></svg>';
        }
        return '<span style="display:inline-flex;align-items:center;justify-content:center;gap:3px;line-height:0;">' + row + '</span>';
    }

    /** Premium award crest — wide plaque shield, navy ribbon, thin gold rim. */
